const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden'; };
const label = b => (b.textContent.trim() || b.getAttribute('aria-label') || b.title || '').replace(/\s+/g, ' ').slice(0, 24);
const legal = b => !!b.closest('.table, .btn-group, .lf-list-row, [role="tablist"]') || b.hasAttribute('aria-pressed') || b.closest('.lf-seg, [data-segmented]');
const bad = [];
for (const b of document.querySelectorAll('.btn-outline-primary')) {
  if (!vis(b) || legal(b)) continue;
  bad.push('無框品牌色按鈕不在列內／分段控制：' + label(b));
}
for (const b of document.querySelectorAll('.btn-outline-danger')) {
  // 停用中的按鈕本身是凹槽底，看得出是按鈕
  if (!vis(b) || legal(b) || b.disabled) continue;
  const cs = getComputedStyle(b);
  if (parseFloat(cs.borderTopWidth) === 0 || cs.borderTopColor === 'rgba(0, 0, 0, 0)' || cs.borderTopColor === 'transparent') bad.push('列外的危險動作入口沒有可見邊框：' + label(b));
}
// 主要按鈕的範圍：每個視窗、表單、清單列（如初始設定的步驟列）與標了 data-primary-scope 的區塊各自至多一顆
const scopeOf = b => b.closest('.modal, form, .list-group-item, [data-primary-scope]') || document.body;
const counts = new Map();
for (const b of document.querySelectorAll('.btn-primary')) {
  if (!vis(b) || b.closest('.lf-sidebar, .lf-topbar, .lf-setup-bar')) continue;
  const s = scopeOf(b);
  counts.set(s, [...(counts.get(s) || []), label(b)]);
}
for (const [s, list] of counts) if (list.length > 1) bad.push((s === document.body ? '頁面本體' : s.matches('.modal') ? '視窗' : '區塊') + '有 ' + list.length + ' 顆實心主要按鈕：' + list.join('、'));
return bad.length ? bad.join('；') : null;
